var cc = tree.root.get_node("/root/Main/ChargeController")
for i in range(cc.unit_selector.item_count):
	if str(cc.unit_selector.get_item_metadata(i)) == "U_BOYZ_T":
		cc.unit_selector.select(i)
		cc.unit_selector.item_selected.emit(i)
		break
return str(cc.active_unit_id)

var cc = tree.root.get_node("/root/Main/ChargeController")
var sel = cc.target_list.get_selected_items()
if sel.size() != 1:
	return "rows=%d" % sel.size()
return str(cc.target_list.get_item_metadata(sel[0]))
